import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type TextFlipDirection = "top" | "right" | "bottom" | "left";
export type TextFlipTrigger = "hover" | "click" | "both";
export type TextFlipStaggerFrom = "first" | "last" | "center" | "random" | number;

export interface TextFlipHandle {
  /** Run one flip cycle. */
  flip: () => Promise<void>;
  /** Cancel in-flight flips and reset glyphs. */
  reset: () => void;
}

export interface TextFlipProps {
  /** The string to render. */
  text: string;
  /** Tag rendered as the outer element. */
  as?: keyof React.JSX.IntrinsicElements;
  /** Outer layout class (color, size, tracking, etc.). */
  className?: string;
  /** Class applied to the front face of each glyph. */
  frontClassName?: string;
  /** Class applied to the back (second) face of each glyph. */
  backClassName?: string;
  /** Front-face color. Omit for theme-aware ink/white. */
  frontColor?: string;
  /** Back-face color. Omit for theme-aware ink/white. */
  backColor?: string;
  /** Axis the characters rotate around when flipping. */
  direction?: TextFlipDirection;
  /** Flip duration per character in seconds. */
  duration?: number;
  /** Delay between each character, in seconds. */
  staggerDuration?: number;
  /** Where the stagger wave originates. */
  staggerFrom?: TextFlipStaggerFrom;
  /** CSS easing. Default approximates the reference spring. */
  easing?: string;
  /** What starts a flip cycle. */
  trigger?: TextFlipTrigger;
  /** Disable pointer triggers (imperative `flip()` still works). */
  disabled?: boolean;
  /** Changing this value forces a flip cycle. */
  replayKey?: string | number;
  /** Fired when a flip cycle begins. */
  onFlipStart?: () => void;
  /** Fired when a flip cycle finishes (including early exits). */
  onFlipComplete?: () => void;
}

/** Approximates reference spring (damping 30 / stiffness 300). */
const SPRINGY_EASE = "cubic-bezier(0.34, 1.4, 0.64, 1)";

const REFERENCE_DURATION = 0.45;

const ROTATION_MAP = {
  top: "rotateX(90deg)",
  right: "rotateY(90deg)",
  bottom: "rotateX(-90deg)",
  left: "rotateY(-90deg)",
} as const;

/** Exact cube offsets from the reference Text3DFlip. */
const CONTAINER_TRANSFORMS = {
  top: "translateZ(-0.5lh)",
  bottom: "translateZ(-0.5lh)",
  left: "rotateY(90deg) translateX(50%) rotateY(-90deg)",
  right: "rotateY(90deg) translateX(50%) rotateY(-90deg)",
} as const;

const FRONT_FACE_TRANSFORMS = {
  top: "translateZ(0.5lh)",
  bottom: "translateZ(0.5lh)",
  left: "rotateY(90deg) translateX(50%) rotateY(-90deg)",
  right: "rotateY(-90deg) translateX(50%) rotateY(90deg)",
} as const;

const SECOND_FACE_TRANSFORMS = {
  top: "rotateX(-90deg) translateZ(0.5lh)",
  right:
    "rotateY(90deg) translateX(50%) rotateY(-90deg) translateX(-50%) rotateY(-90deg) translateX(50%)",
  bottom: "rotateX(90deg) translateZ(0.5lh)",
  left: "rotateY(90deg) translateX(50%) rotateY(-90deg) translateX(50%) rotateY(-90deg) translateX(50%)",
} as const;

const CHAR_SELECTOR = "[data-wensity-text-flip-char]";

let graphemeSegmenter: Intl.Segmenter | null = null;

function getGraphemeSegmenter(): Intl.Segmenter | null {
  if (typeof Intl === "undefined" || !("Segmenter" in Intl)) return null;
  graphemeSegmenter ??= new Intl.Segmenter("en", { granularity: "grapheme" });
  return graphemeSegmenter;
}

function splitIntoCharacters(value: string): string[] {
  const segmenter = getGraphemeSegmenter();
  if (segmenter) {
    return Array.from(segmenter.segment(value), ({ segment }) => segment);
  }
  return Array.from(value);
}

type WordChars = {
  characters: string[];
  needsSpace: boolean;
};

function buildWords(text: string): WordChars[] {
  const words = text.length > 0 ? text.split(" ") : [""];
  return words.map((word, i) => ({
    characters: splitIntoCharacters(word.length > 0 ? word : "\u00A0"),
    needsSpace: i !== words.length - 1,
  }));
}

function getStaggerDelay(
  index: number,
  total: number,
  staggerFrom: TextFlipStaggerFrom,
  staggerDuration: number,
  randomOrigin: number,
): number {
  if (total <= 1 || staggerDuration <= 0) return 0;
  if (staggerFrom === "first") return index * staggerDuration;
  if (staggerFrom === "last") return (total - 1 - index) * staggerDuration;
  if (staggerFrom === "center") {
    const center = Math.floor(total / 2);
    return Math.abs(center - index) * staggerDuration;
  }
  if (staggerFrom === "random") {
    return Math.abs(randomOrigin - index) * staggerDuration;
  }
  return Math.abs(staggerFrom - index) * staggerDuration;
}

function prefersReducedMotion(): boolean {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") {
    return false;
  }
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

function cancelAnimations(list: Animation[]) {
  for (const animation of list) {
    try {
      animation.cancel();
    } catch {
      // already finished
    }
  }
}

/**
 * TextFlip — reference Text3DFlip cube + WAAPI springy flip.
 *
 * Same DOM/geometry as the Motion demo. Animation is WAAPI because
 * `useAnimate` + transform springs were silently no-oping here.
 */
export const TextFlip = React.forwardRef<TextFlipHandle, TextFlipProps>(
  function TextFlip(
    {
      text,
      as: ElementTag = "span",
      className,
      frontClassName,
      backClassName,
      frontColor,
      backColor,
      direction = "top",
      duration = REFERENCE_DURATION,
      staggerDuration = 0.05,
      staggerFrom = "first",
      easing = SPRINGY_EASE,
      trigger = "hover",
      disabled = false,
      replayKey,
      onFlipStart,
      onFlipComplete,
    },
    ref,
  ) {
    const rootRef = React.useRef<HTMLSpanElement | null>(null);
    const isAnimatingRef = React.useRef(false);
    const isMountedRef = React.useRef(true);
    const randomOriginRef = React.useRef(0);
    const replaySeenRef = React.useRef(replayKey);
    const runningRef = React.useRef<Animation[]>([]);
    const reduceMotionRef = React.useRef(false);
    const [reduceMotion, setReduceMotion] = React.useState(false);

    const words = React.useMemo(() => buildWords(text), [text]);
    const totalChars = React.useMemo(
      () => words.reduce((sum, word) => sum + word.characters.length, 0),
      [words],
    );

    const containerTransform = CONTAINER_TRANSFORMS[direction];
    const flipTransform = ROTATION_MAP[direction];

    React.useEffect(() => {
      isMountedRef.current = true;
      const reduced = prefersReducedMotion();
      reduceMotionRef.current = reduced;
      setReduceMotion(reduced);

      const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
      const onChange = () => {
        reduceMotionRef.current = mq.matches;
        setReduceMotion(mq.matches);
      };
      mq.addEventListener("change", onChange);

      return () => {
        isMountedRef.current = false;
        isAnimatingRef.current = false;
        cancelAnimations(runningRef.current);
        runningRef.current = [];
        mq.removeEventListener("change", onChange);
      };
    }, []);

    React.useEffect(() => {
      if (staggerFrom !== "random" || totalChars <= 0) return;
      randomOriginRef.current = Math.floor(Math.random() * totalChars);
    }, [staggerFrom, totalChars]);

    const snapRest = React.useCallback(() => {
      const root = rootRef.current;
      cancelAnimations(runningRef.current);
      runningRef.current = [];
      if (!root) return;
      root.querySelectorAll<HTMLElement>(CHAR_SELECTOR).forEach((node) => {
        node.style.transform = containerTransform;
        node.style.willChange = "auto";
      });
    }, [containerTransform]);

    const runFlip = React.useCallback(async () => {
      if (reduceMotionRef.current) return;

      const root = rootRef.current;
      if (!root || totalChars === 0) return;
      if (isAnimatingRef.current) return;

      const nodes = Array.from(
        root.querySelectorAll<HTMLElement>(CHAR_SELECTOR),
      );
      if (nodes.length === 0) return;

      isAnimatingRef.current = true;
      onFlipStart?.();

      const durationMs = Math.round(
        Math.max(180, Math.min(1200, duration * 1000)),
      );

      try {
        cancelAnimations(runningRef.current);

        const delays = nodes.map((_, i) =>
          getStaggerDelay(
            i,
            nodes.length,
            staggerFrom,
            Math.max(0, staggerDuration),
            randomOriginRef.current,
          ),
        );

        const animations = nodes.map((node, i) => {
          node.style.willChange = "transform";
          // Start from the cube rest pose (same as reference).
          node.style.transform = containerTransform;

          return node.animate(
            [
              { transform: containerTransform },
              { transform: flipTransform },
            ],
            {
              duration: durationMs,
              delay: delays[i] * 1000,
              easing,
              fill: "forwards",
            },
          );
        });

        runningRef.current = animations;

        await Promise.all(
          animations.map((animation) =>
            animation.finished.catch(() => {
              // cancelled
            }),
          ),
        );

        if (!isMountedRef.current) return;

        // Instant reset to cube rest — same beat as the reference.
        snapRest();
      } catch {
        snapRest();
      } finally {
        isAnimatingRef.current = false;
        if (isMountedRef.current) onFlipComplete?.();
      }
    }, [
      containerTransform,
      duration,
      easing,
      flipTransform,
      onFlipComplete,
      onFlipStart,
      snapRest,
      staggerDuration,
      staggerFrom,
      totalChars,
    ]);

    React.useImperativeHandle(
      ref,
      () => ({
        flip: () => runFlip(),
        reset: () => {
          isAnimatingRef.current = false;
          snapRest();
        },
      }),
      [runFlip, snapRest],
    );

    React.useEffect(() => {
      if (replayKey === undefined) return;
      if (replaySeenRef.current === replayKey) return;
      replaySeenRef.current = replayKey;
      void runFlip();
    }, [replayKey, runFlip]);

    const allowHover = !disabled && (trigger === "hover" || trigger === "both");
    const allowClick = !disabled && (trigger === "click" || trigger === "both");

    if (reduceMotion) {
      return React.createElement(
        ElementTag,
        { className: cn("inline-block", className) },
        text,
      );
    }

    // Interactive root owns hover + sizing. `as` is only a semantic wrapper.
    const interactive = (
      <span
        ref={rootRef}
        className={cn(
          "relative inline-flex flex-wrap items-baseline overflow-visible",
          "[perspective:1000px]",
          allowHover || allowClick ? "cursor-default" : undefined,
          className,
        )}
        onPointerEnter={
          allowHover
            ? () => {
                void runFlip();
              }
            : undefined
        }
        onClick={
          allowClick
            ? () => {
                void runFlip();
              }
            : undefined
        }
      >
        <span className="sr-only">{text}</span>

        {words.map((word, wordIndex) => (
          <span key={wordIndex} aria-hidden className="inline-flex">
            {word.characters.map((char, charIndex) => (
              <CharBox
                key={`${wordIndex}-${charIndex}`}
                char={char}
                direction={direction}
                frontClassName={frontClassName}
                backClassName={backClassName}
                frontColor={frontColor}
                backColor={backColor}
              />
            ))}
            {word.needsSpace ? <span className="whitespace-pre"> </span> : null}
          </span>
        ))}
      </span>
    );

    if (ElementTag === "span") return interactive;

    return React.createElement(ElementTag, null, interactive);
  },
);

TextFlip.displayName = "TextFlip";

const CharBox = React.memo(function CharBox({
  char,
  direction,
  frontClassName,
  backClassName,
  frontColor,
  backColor,
}: {
  char: string;
  direction: TextFlipDirection;
  frontClassName?: string;
  backClassName?: string;
  frontColor?: string;
  backColor?: string;
}) {
  const glyph = char === " " ? "\u00A0" : char;

  return (
    // Reference structure: ONE element holds cube offset + is animated.
    <span
      data-wensity-text-flip-char=""
      className="inline transform-3d"
      style={{ transform: CONTAINER_TRANSFORMS[direction] }}
    >
      <span
        className={cn(
          "relative inline-block h-[1lh] whitespace-pre backface-hidden",
          !frontColor && "text-zinc-900 dark:text-white",
          frontClassName,
        )}
        style={{
          transform: FRONT_FACE_TRANSFORMS[direction],
          ...(frontColor ? { color: frontColor } : null),
        }}
      >
        {glyph}
      </span>
      <span
        className={cn(
          "absolute top-0 left-0 inline-block h-[1lh] whitespace-pre backface-hidden",
          !backColor && !frontColor && "text-zinc-900 dark:text-white",
          backClassName,
        )}
        style={{
          transform: SECOND_FACE_TRANSFORMS[direction],
          ...(backColor
            ? { color: backColor }
            : frontColor
              ? { color: frontColor }
              : null),
        }}
      >
        {glyph}
      </span>
    </span>
  );
});
